-- NeoContract / Fanasa catalog extension
CREATE SCHEMA IF NOT EXISTS contracts;
SET search_path TO contracts, public;
CREATE EXTENSION IF NOT EXISTS pgcrypto;


-- Fanasa catalog, SLA, revenue and CRM extension (tenant-scoped).
-- Catalog values are browser-observed-unverified; the source was not independently verified.
CREATE TABLE IF NOT EXISTS catalog_sources (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  source_key text NOT NULL, source_url text NOT NULL, observation_method text NOT NULL DEFAULT 'browser DOM snapshot',
  verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')),
  observed_at timestamptz, fetched_at timestamptz, http_status integer, content_sha256 text,
  metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, source_key)
);
CREATE TABLE IF NOT EXISTS catalog_zones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  source_id uuid REFERENCES catalog_sources(id) ON DELETE SET NULL, zone_key text NOT NULL, name text NOT NULL,
  display_order integer NOT NULL DEFAULT 0, verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')),
  metadata jsonb NOT NULL DEFAULT '{}', UNIQUE (tenant_id, zone_key)
);
CREATE TABLE IF NOT EXISTS catalog_centers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  zone_id uuid NOT NULL REFERENCES catalog_zones(id) ON DELETE RESTRICT, source_id uuid REFERENCES catalog_sources(id) ON DELETE SET NULL,
  center_key text NOT NULL, name text NOT NULL, verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')),
  metadata jsonb NOT NULL DEFAULT '{}', UNIQUE (tenant_id, center_key)
);
CREATE TABLE IF NOT EXISTS catalog_services (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  center_id uuid NOT NULL REFERENCES catalog_centers(id) ON DELETE RESTRICT, source_id uuid REFERENCES catalog_sources(id) ON DELETE SET NULL,
  service_code text NOT NULL, name text NOT NULL, pricing_model text NOT NULL CHECK (pricing_model IN ('per_user','usage','fixed','hybrid','project','overhead','included')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','retired')), verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')),
  metadata jsonb NOT NULL DEFAULT '{}', UNIQUE (tenant_id, service_code)
);
CREATE TABLE IF NOT EXISTS sla_tiers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, source_id uuid REFERENCES catalog_sources(id) ON DELETE SET NULL,
  code text NOT NULL, label text NOT NULL, availability_pct numeric(5,2) CHECK (availability_pct BETWEEN 0 AND 100), first_response_minutes integer CHECK (first_response_minutes >= 0), resolution_target_minutes integer CHECK (resolution_target_minutes >= 0), coverage text, observed_service_count integer CHECK (observed_service_count >= 0),
  verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')), metadata jsonb NOT NULL DEFAULT '{}', UNIQUE (tenant_id, code)
);
CREATE TABLE IF NOT EXISTS catalog_service_sla (
  service_id uuid NOT NULL REFERENCES catalog_services(id) ON DELETE CASCADE, sla_tier_id uuid NOT NULL REFERENCES sla_tiers(id) ON DELETE RESTRICT, is_default boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY (service_id, sla_tier_id)
);
CREATE TABLE IF NOT EXISTS revenue_models (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, source_id uuid REFERENCES catalog_sources(id) ON DELETE SET NULL,
  code text NOT NULL, name text NOT NULL, model_type text NOT NULL CHECK (model_type IN ('per_user','usage','fixed','hybrid','project','overhead','included')), unit_label text, billing_period text, description text, pricing_config jsonb NOT NULL DEFAULT '{}',
  verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')), metadata jsonb NOT NULL DEFAULT '{}', UNIQUE (tenant_id, code)
);
CREATE TABLE IF NOT EXISTS catalog_service_revenue_models (
  service_id uuid NOT NULL REFERENCES catalog_services(id) ON DELETE CASCADE, revenue_model_id uuid NOT NULL REFERENCES revenue_models(id) ON DELETE RESTRICT, is_default boolean NOT NULL DEFAULT false, unit_price numeric(20,4), currency char(3) DEFAULT 'IRR', metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY (service_id, revenue_model_id)
);
CREATE TABLE IF NOT EXISTS account_managers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, manager_code text NOT NULL, display_name text NOT NULL, email text, phone text, portfolio text, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')), verification_status text NOT NULL DEFAULT 'demo-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, manager_code)
);
CREATE TABLE IF NOT EXISTS customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, customer_code text NOT NULL, legal_name text NOT NULL, party_id uuid REFERENCES parties(id) ON DELETE SET NULL, account_manager_id uuid REFERENCES account_managers(id) ON DELETE SET NULL, segment text, status text NOT NULL DEFAULT 'active' CHECK (status IN ('lead','active','paused','churned')), primary_contact_name text, primary_contact_email text, verification_status text NOT NULL DEFAULT 'demo-unverified' CHECK (verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, customer_code)
);
CREATE TABLE IF NOT EXISTS customer_service_subscriptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE, service_id uuid NOT NULL REFERENCES catalog_services(id) ON DELETE RESTRICT, account_manager_id uuid REFERENCES account_managers(id) ON DELETE SET NULL, sla_tier_id uuid REFERENCES sla_tiers(id) ON DELETE RESTRICT, revenue_model_id uuid REFERENCES revenue_models(id) ON DELETE RESTRICT, contract_id uuid REFERENCES contracts(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','active','paused','ended')), quantity numeric(20,4), unit_price numeric(20,4), currency char(3) DEFAULT 'IRR', starts_on date, ends_on date, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_on IS NULL OR starts_on IS NULL OR ends_on >= starts_on)
);
CREATE INDEX IF NOT EXISTS catalog_services_tenant_idx ON catalog_services(tenant_id, status);
CREATE INDEX IF NOT EXISTS subscriptions_tenant_status_idx ON customer_service_subscriptions(tenant_id, status);
CREATE INDEX IF NOT EXISTS customers_tenant_manager_idx ON customers(tenant_id, account_manager_id);
CREATE OR REPLACE FUNCTION contracts.customers_set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS customers_updated_at ON customers;
CREATE TRIGGER customers_updated_at BEFORE UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION contracts.customers_set_updated_at();

-- Tenant-scoped source snapshot. Values below remain unverified until an operator confirms them.

-- Contract-level service snapshot. Catalog edits never rewrite historical contract lines.
CREATE TABLE IF NOT EXISTS contract_services (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  contract_id uuid NOT NULL REFERENCES contracts(id) ON DELETE CASCADE,
  service_id uuid REFERENCES catalog_services(id) ON DELETE SET NULL,
  service_code text NOT NULL,
  service_name_snapshot text NOT NULL,
  pricing_model_snapshot text CHECK (pricing_model_snapshot IS NULL OR pricing_model_snapshot IN ('per_user','usage','fixed','hybrid','project','overhead','included')),
  sla_tier_snapshot text,
  delivery text,
  quantity numeric(20,4) CHECK (quantity IS NULL OR quantity >= 0),
  unit_price numeric(20,4) CHECK (unit_price IS NULL OR unit_price >= 0),
  currency char(3) NOT NULL DEFAULT 'IRR',
  source_verification_status text NOT NULL DEFAULT 'browser-observed-unverified' CHECK (source_verification_status IN ('browser-observed-unverified','demo-unverified','verified','deprecated')),
  metadata jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS contract_services_tenant_contract_idx ON contract_services(tenant_id, contract_id);
CREATE INDEX IF NOT EXISTS contract_services_service_idx ON contract_services(tenant_id, service_code);
